import{_ as e,o as a,c as i,U as s}from"./chunks/framework.GEUfU7f1.js";const b=JSON.parse('{"title":"每日一题 - 202406","description":"","frontmatter":{"readingTime":false,"hidden":true,"outline":3},"headers":[],"relativePath":"interview/question-by-day/2024/6.md","filePath":"interview/question-by-day/2024/6.md","lastUpdated":1717490403000}'),t={name:"interview/question-by-day/2024/6.md"},o=s(`<h1 id="每日一题-202406" tabindex="-1">每日一题 - 202406 <a class="header-anchor" href="#每日一题-202406" aria-label="Permalink to &quot;每日一题 - 202406&quot;">​</a></h1><h2 id="_6-4" tabindex="-1">6-4 <a class="header-anchor" href="#_6-4" aria-label="Permalink to &quot;6-4&quot;">​</a></h2><h3 id="什么是-csrf-攻击" tabindex="-1">什么是 CSRF 攻击？ <a class="header-anchor" href="#什么是-csrf-攻击" aria-label="Permalink to &quot;什么是 CSRF 攻击？&quot;">​</a></h3><p><code>CSRF</code> (Cross-site request forgery)，跨站请求伪造，又称为 <code>one-click attack</code>，是一种挟制用户在当前已登录的Web应用程序上执行非本意的操作的攻击方法。跟跨网站脚本（XSS）相比，XSS 利用的是用户对指定网站的信任，CSRF 利用的是网站对用户网页浏览器的信任。</p><ol><li>使用 JSON API。当进行 CSRF 攻击时，请求体通过 <code>&lt;form&gt;</code> 构建，请求头为 <code>application/www-form-urlencoded</code>。它难以发送 JSON 数据被服务器所理解。</li><li>CSRF Token。生成一个随机的 token，切勿放在 cookie 中，每次请求手动携带该 token 进行校验。</li><li>SameSite Cookie。设置为 Lax 或者 Strict，禁止发送第三方 Cookie。</li></ol><h2 id="_6-3" tabindex="-1">6-3 <a class="header-anchor" href="#_6-3" aria-label="Permalink to &quot;6-3&quot;">​</a></h2><h3 id="简述-http-的缓存机制" tabindex="-1">简述 http 的缓存机制 <a class="header-anchor" href="#简述-http-的缓存机制" aria-label="Permalink to &quot;简述 http 的缓存机制&quot;">​</a></h3><p><strong>缓存过程</strong></p><blockquote><p>浏览器与服务器通信的方式为应答模式，即是：浏览器发起HTTP请求 – 服务器响应该请求。那么浏览器第一次向服务器发起该请求后拿到请求结果，会根据响应报文中HTTP头的缓存标识，决定是否缓存结果，是则将请求结果和缓存标识存入浏览器缓存中。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/4/19/162db6359673e7d0~tplv-t2oaga2asx-jj-mark:3024:0:0:0:q75.awebp" alt="img"></p></blockquote><p>Http 缓存分为以下两种，两者都是通过 HTTP 响应头控制缓存</p><ol><li><code>强制缓存</code></li><li><code>协商缓存</code></li></ol><h4 id="强制缓存" tabindex="-1">强制缓存 <a class="header-anchor" href="#强制缓存" aria-label="Permalink to &quot;强制缓存&quot;">​</a></h4><p>​ 强制缓存就是向浏览器缓存查找该请求结果，并根据该结果的缓存规则来决定是否使用该缓存结果的过程，强制缓存的情况主要有三种(暂不分析协商缓存过程)；</p><p>1、不存在该缓存结果和缓存标识，强制缓存失效，则直接向服务器发起请求（跟第一次发起请求一致）</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/4/19/162db63596c9de23~tplv-t2oaga2asx-jj-mark:3024:0:0:0:q75.awebp" alt="img"></p><p>2、存在该缓存结果和缓存标识，但该结果已失效，强制缓存失效，则使用协商缓存(暂不分析)</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/4/19/162db63597182316~tplv-t2oaga2asx-jj-mark:3024:0:0:0:q75.awebp" alt="img"></p><p>3、存在该缓存结果和缓存标识，且该结果尚未失效，强制缓存生效，直接返回该结果</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/4/19/162db6359acd19d3~tplv-t2oaga2asx-jj-mark:3024:0:0:0:q75.awebp" alt="img"></p><p>与之相关的 <code>Response Headers</code> 有以下几个：</p><h5 id="expires" tabindex="-1">Expires <a class="header-anchor" href="#expires" aria-label="Permalink to &quot;Expires&quot;">​</a></h5><p>Expires是HTTP/1.0控制网页缓存的字段，其值为服务器返回该请求结果缓存的到期时间，即再次发起该请求时，如果客户端的时间小于Expires的值时，直接使用缓存结果。</p><blockquote><p>Expires是HTTP/1.0的字段，但是现在浏览器默认使用的是HTTP/1.1，那么在HTTP/1.1中网页缓存还是否由Expires控制？</p></blockquote><p>到了HTTP/1.1，Expire已经被Cache-Control替代，原因在于Expires控制缓存的原理是使用客户端的时间与服务端返回的时间做对比，那么如果客户端与服务端的时间因为某些原因（例如时区不同；客户端和服务端有一方的时间不准确）发生误差，那么强制缓存则会直接失效，这样的话强制缓存的存在则毫无意义，那么Cache-Control又是如何控制的呢？</p><h5 id="cache-control" tabindex="-1">Cache-Control <a class="header-anchor" href="#cache-control" aria-label="Permalink to &quot;Cache-Control&quot;">​</a></h5><p>在HTTP/1.1中，Cache-Control是最重要的规则，主要用于控制网页缓存，主要取值为：</p><ul><li>public：所有内容都将被缓存（客户端和代理服务器都可缓存）</li><li>private：所有内容只有客户端可以缓存，Cache-Control的默认取值</li><li>no-cache：客户端缓存内容，但是是否使用缓存则需要经过协商缓存来验证决定</li><li>no-store：所有内容都不会被缓存，即不使用强制缓存，也不使用协商缓存</li><li>max-age=xxx (xxx is numeric)：缓存内容将在xxx秒后失效</li></ul><blockquote><p>HTTP响应报文中expires的时间值，是一个绝对值。</p><p>HTTP响应报文中Cache-Control为max-age=600，是相对值。</p><p>由于Cache-Control的优先级比expires，那么直接根据Cache-Control的值进行缓存，意思就是说在600秒内再次发起该请求，则会直接使用缓存结果，强制缓存生效。</p></blockquote><h4 id="协商缓存" tabindex="-1">协商缓存 <a class="header-anchor" href="#协商缓存" aria-label="Permalink to &quot;协商缓存&quot;">​</a></h4><p>协商缓存就是强制缓存失效后，浏览器携带缓存标识向服务器发起请求，由服务器根据缓存标识决定是否使用缓存的过程，主要有以下两种情况：</p><p>1、协商缓存生效，返回304</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/4/19/162db635cbfff69d~tplv-t2oaga2asx-jj-mark:3024:0:0:0:q75.awebp" alt="img"></p><p>2、协商缓存失效，返回200和请求结果结果</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/4/19/162db635cf070ff5~tplv-t2oaga2asx-jj-mark:3024:0:0:0:q75.awebp" alt="img"></p><p>与之相关的 <code>Request/Response Headers</code> 有以下几个</p><h5 id="last-modified-if-modified-since" tabindex="-1">Last-Modified / If-Modified-Since <a class="header-anchor" href="#last-modified-if-modified-since" aria-label="Permalink to &quot;Last-Modified / If-Modified-Since&quot;">​</a></h5><p>Last-Modified是服务器响应请求时，返回该资源文件在服务器最后被修改的时间；</p><p>If-Modified-Since则是客户端再次发起该请求时，携带上次请求返回的Last-Modified值，通过此字段值告诉服务器该资源上次请求返回的最后被修改时间。服务器收到该请求，发现请求头含有If-Modified-Since字段，则会根据If-Modified-Since的字段值与该资源在服务器的最后被修改时间做对比，若服务器的资源最后被修改时间大于If-Modified-Since的字段值，则重新返回资源，状态码为200；否则则返回304，代表资源无更新，可继续使用缓存文件。</p><h5 id="etag-if-none-match" tabindex="-1">Etag / If-None-Match <a class="header-anchor" href="#etag-if-none-match" aria-label="Permalink to &quot;Etag / If-None-Match&quot;">​</a></h5><p>Etag是服务器响应请求时，返回当前资源文件的一个唯一标识(由服务器生成)；</p><p>If-None-Match是客户端再次发起该请求时，携带上次请求返回的唯一标识Etag值，通过此字段值告诉服务器该资源上次请求返回的唯一标识值。服务器收到该请求后，发现该请求头中含有If-None-Match，则会根据If-None-Match的字段值与该资源在服务器的Etag值做对比，一致则返回304，代表资源无更新，继续使用缓存文件；不一致则重新返回资源文件，状态码为200</p><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h4><p>强制缓存优先于协商缓存进行，若强制缓存(Expires和Cache-Control)生效则直接使用缓存，若不生效则进行协商缓存(Last-Modified / If-Modified-Since和Etag / If-None-Match)，协商缓存由服务器决定是否使用缓存，若协商缓存失效，那么代表该请求的缓存失效，重新获取请求结果，再存入浏览器缓存中；生效则返回304，继续使用缓存，主要过程如下：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/4/19/162db635ed5f6d26~tplv-t2oaga2asx-jj-mark:3024:0:0:0:q75.awebp" alt="img"></p><h2 id="_6-2" tabindex="-1">6-2 <a class="header-anchor" href="#_6-2" aria-label="Permalink to &quot;6-2&quot;">​</a></h2><h3 id="http-常见的状态码" tabindex="-1">http 常见的状态码 <a class="header-anchor" href="#http-常见的状态码" aria-label="Permalink to &quot;http 常见的状态码&quot;">​</a></h3><blockquote><ul><li><code>1XX </code>表示消息</li><li><code>2XX </code>表示成功</li><li><code>3XX</code> 表示重定向</li><li><code>4XX</code> 表示客户端错误</li><li><code>5XX</code> 表示服务端错误</li></ul></blockquote><p><code>200</code>：最喜欢见到的状态码，表示请求成功</p><p><code>301</code>：永久重定向</p><p><code>302</code>：临时重定向</p><p><code>304</code>：自上次请求，未修改的文件</p><blockquote><p><strong>http 状态码中 301，302和307有什么区别</strong></p><ul><li>301，Moved Permanently。永久重定向，该操作比较危险，需要谨慎操作：如果设置了301，但是一段时间后又想取消，但是浏览器中已经有了缓存，还是会重定向。</li><li>302，Found。临时重定向，但是会在重定向的时候改变 method: 把 POST 改成 GET，于是有了 307</li><li>307，Temporary Redirect。临时重定向，在重定向时不会改变 method</li></ul></blockquote><p><code>400</code>：错误的请求</p><p><code>401</code>：未被授权，需要身份验证，例如token信息等等</p><p><code>403</code>：请求被拒绝</p><p><code>404</code>：资源缺失，接口不存在或请求的文件不存在等等</p><p><code>405</code>：请求方法不对，需要POST这条资源而你却使用了GET</p><p><code>500</code>：服务器端的未知错误</p><p><code>502</code>：网关错误</p><p><code>503</code>：服务暂时无法使用</p><p><code>504</code>：网关超时，上游应用层迟迟未响应</p><h2 id="_6-1" tabindex="-1">6-1 <a class="header-anchor" href="#_6-1" aria-label="Permalink to &quot;6-1&quot;">​</a></h2><h3 id="浏览器中如何实现剪切板复制内容的功能" tabindex="-1">浏览器中如何实现剪切板复制内容的功能？ <a class="header-anchor" href="#浏览器中如何实现剪切板复制内容的功能" aria-label="Permalink to &quot;浏览器中如何实现剪切板复制内容的功能？&quot;">​</a></h3><h4 id="方法1-第三方库-clipboard-copy-opens-in-a-new-tab" tabindex="-1">方法1：第三方库 <a href="https://github.com/feross/clipboard-copy/blob/master/index.js" target="_blank" rel="noreferrer">clipboard-copy(opens in a new tab)</a> <a class="header-anchor" href="#方法1-第三方库-clipboard-copy-opens-in-a-new-tab" aria-label="Permalink to &quot;方法1：第三方库 [clipboard-copy(opens in a new tab)](https://github.com/feross/clipboard-copy/blob/master/index.js)&quot;">​</a></h4><p>使用 <code>Clipboard API</code> 进行实现是目前最为推荐的方式</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">navigator.clipboard.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">writeText</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(text);</span></span></code></pre></div><blockquote><p>而对于一些不支持 <code>Clipboard API</code> 的浏览器，使用以下 API 进行复制</p></blockquote><h4 id="方法2-选中-selection-api-range-api" tabindex="-1">方法2：选中: Selection API/Range API <a class="header-anchor" href="#方法2-选中-selection-api-range-api" aria-label="Permalink to &quot;方法2：选中: Selection API/Range API&quot;">​</a></h4><blockquote><p><a href="https://developer.mozilla.org/en-US/docs/Web/API/Selection" target="_blank" rel="noreferrer">Selection API</a></p><p><code>Selection</code> 对象表示用户选择的文本范围或插入符号的当前位置。它代表页面中的文本选区，可能横跨多个元素。文本选区由用户拖拽鼠标经过文字而产生。要获取用于检查或修改的 Selection 对象，请调用 <code>window.getSelection()</code>。</p><p><code>Selection</code> 对象所对应的是用户所选择的 <code>ranges</code>（区域），俗称拖蓝。默认情况下，该函数只针对一个区域。</p><p><strong>方法</strong>：</p><p><code>getRangeAt</code>：返回选区包含的指定区域（<code>Range</code>）的<strong>引用</strong>。</p><p><code>collapse</code>：将当前的选区折叠为一个点。</p><p><code>extend</code>：将选区的焦点移动到一个特定的位置。</p><p><code>modify</code>：修改当前的选区。</p><p><code>collapseToStart</code>：将当前的选区折叠到起始点。</p><p><code>collapseToEnd</code>：将当前的选区折叠到最末尾的一个点。</p><p><code>selectAllChildren</code>：将某一指定节点的子节点框入选区。</p><p><code>addRange</code>：一个区域（<a href="https://developer.mozilla.org/zh-CN/docs/Web/API/Range" target="_blank" rel="noreferrer"><code>Range</code></a>）对象将被加入选区。</p><p><code>removeRange</code>：从选区中移除一个区域。</p><p><code>removeAllRanges</code>：将所有的区域都从选区中移除。</p><p><code>deleteFromDocument</code>：从页面中删除选区中的内容。</p><p><code>selectionLanguageChange</code></p><p>当键盘的朝向发生改变后修改指针的 Bidi 优先级。</p><p><code>toString</code>：返回当前选区的纯文本内容。</p><p><code>containsNode</code>：判断某一个 <code>Node</code> 是否为当前选区的一部分。</p></blockquote><p><strong>选中</strong>：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> selection</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getSelection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> range</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createRange</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// RangeAPI: 制造区域</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">range.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">selectNodeContents</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(element);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Selection: 选中区域</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">selection.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addRange</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(range);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">selectedText </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> selection.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><p><strong>取消选中</strong>：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getSelection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">removeAllRanges</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h4 id="方法3-复制execcommand" tabindex="-1">方法3：复制execCommand <a class="header-anchor" href="#方法3-复制execcommand" aria-label="Permalink to &quot;方法3：复制execCommand&quot;">​</a></h4><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">document.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execCommand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;copy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div>`,75),p=[o];function l(n,d,c,r,h,k){return a(),i("div",null,p)}const m=e(t,[["render",l]]);export{b as __pageData,m as default};
